# django/urls/base.py:21-24  (django.urls.base.resolve)
def resolve(path, urlconf=None):
    if urlconf is None:
        urlconf = get_urlconf()
    return get_resolver(urlconf).resolve(path)

# django/urls/resolvers.py:105-108  (django.urls.resolvers.get_resolver)
def get_resolver(urlconf=None):
    if urlconf is None:
        urlconf = settings.ROOT_URLCONF
    return _get_cached_resolver(urlconf)
